#!/usr/bin/env python3
# Map incident artifacts to MITRE ATT&CK techniques, ordered by kill chain.
import json
amap = json.load(open("attack_map.json"))
chain = []
marker = None
for ln in open("events.jsonl"):
    e = json.loads(ln)
    if e["EventID"] == 1 and "mshta" in e.get("Image", ""):
        chain.append(amap["1:mshta"]); 
    if e["EventID"] == 106:
        chain.append(amap["106"])
    if e["EventID"] == 10 and "lsass" in e.get("TargetImage", ""):
        chain.append(amap["10:lsass"])
    if e["EventID"] == 1102:
        chain.append(amap["1102"])
    cl = e.get("CommandLine", "")
    if "nto{" in cl:
        marker = cl
for step in chain:
    print("[%-18s] %s" % (step["tactic"], step["tech"]))
print("artifact marker:", marker.split("marker\\")[-1].split()[0] if marker else "none")
